def c_str(s):
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n') + '"'


def main():
    root = Path(__file__).resolve().parents[2]
    seen = {}
    for row in T:
        assert len(row) == 5, row
        if row[0] in seen and seen[row[0]] != row:
            raise SystemExit(f"two different translations for {row[0]!r}")
        seen[row[0]] = row
    # every English key must appear in the code, or it can never match
    code = ''.join(p.read_text() for p in (root / 'apps/sloppy').glob('sloppy*.[ci]*'))
    code = code.replace('" "', '').replace('"\n', '').replace('\\n', '\n')
    import re
    joined = re.sub(r'"\s*\n\s*"', '', ''.join(p.read_text() for p in (root / 'apps/sloppy').glob('sloppy*.[ci]*')))
    joined = joined.replace('" WF_NAME "', 'GabagoolOS R1').replace('\\n', '\n')
    missing = [k for k in seen if k not in joined]
    if missing:
        print("not found in the code (check spelling):")
        for m in missing:
            print("  ", repr(m))
    untranslated = [k for k in seen if k not in AR]
    unknown = [k for k in AR if k not in seen]
    if untranslated or unknown:
        raise SystemExit(f"arabic.py: no Arabic for {untranslated}, no row for {unknown}")
    out = root / 'apps/sloppy/sloppy_lang_table.h'
    lines = ["/* Generated by sloppy-dev/lang/translations.py. Do not edit. */"]
    for en, es, fr, de, he in seen.values():
        lines.append("{ %s, { %s, %s, %s, %s, %s } }," % tuple(c_str(x) for x in (en, es, fr, de, he, AR[en])))
    out.write_text('\n'.join(lines) + '\n')
    print(f"{len(seen)} phrases -> {out.relative_to(root)}")


if __name__ == '__main__':
    main()
